-- Sprint 9B additive schema. IDs are generated by the application. No destructive DDL.
CREATE TABLE IF NOT EXISTS baseline_brands (
  id uuid PRIMARY KEY,
  qloo_id text NOT NULL UNIQUE,
  name text NOT NULL,
  lookup_name text NOT NULL,
  qloo_type text NOT NULL CHECK (qloo_type IN ('brand', 'urn:entity:brand')),
  resolution_state text NOT NULL CHECK (resolution_state = 'RESOLVED'),
  verified_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS baseline_brands_lookup_idx ON baseline_brands (lookup_name);

CREATE TABLE IF NOT EXISTS baseline_resolutions (
  id uuid PRIMARY KEY,
  access_scope text NOT NULL,
  input_name text NOT NULL,
  selected_qloo_id text,
  status text NOT NULL CHECK (status IN ('PENDING','RESOLVED','AMBIGUOUS','NOT_FOUND','TEMPORARILY_UNAVAILABLE')),
  brand_id uuid REFERENCES baseline_brands(id),
  candidates jsonb NOT NULL DEFAULT '[]',
  access_token_hash text NOT NULL,
  provider_correlation_id text,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz
);
CREATE INDEX IF NOT EXISTS baseline_resolutions_scope_recent_idx ON baseline_resolutions (access_scope,created_at DESC);

CREATE TABLE IF NOT EXISTS baseline_scans (
  id uuid PRIMARY KEY,
  brand_id uuid NOT NULL REFERENCES baseline_brands(id),
  resolution_id uuid NOT NULL REFERENCES baseline_resolutions(id),
  template_version text NOT NULL,
  schema_version text NOT NULL,
  status text NOT NULL CHECK (status IN ('CREATED','QUEUED','RUNNING','COMPLETE','PARTIAL','NEEDS_BRAND_CONFIRMATION','INSUFFICIENT_EVIDENCE','FAILED','INTERRUPTED','CANCELLED')),
  requested_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  finished_at timestamptz,
  access_scope text NOT NULL,
  access_token_hash text NOT NULL,
  idempotency_key text NOT NULL,
  request_hash text NOT NULL,
  provider_call_count integer NOT NULL DEFAULT 0 CHECK (provider_call_count BETWEEN 0 AND 7),
  partial_failure_summary text,
  result_artifact_id uuid,
  cache_source_scan_id uuid REFERENCES baseline_scans(id),
  lease_owner uuid,
  lease_until timestamptz,
  heartbeat_at timestamptz,
  UNIQUE (access_scope, idempotency_key)
);
CREATE INDEX IF NOT EXISTS baseline_scans_status_lease_idx ON baseline_scans (status, lease_until);
CREATE INDEX IF NOT EXISTS baseline_scans_brand_recent_idx ON baseline_scans (brand_id, finished_at DESC);

CREATE TABLE IF NOT EXISTS baseline_stages (
  scan_id uuid NOT NULL REFERENCES baseline_scans(id),
  stage text NOT NULL,
  status text NOT NULL CHECK (status IN ('PENDING','RUNNING','COMPLETE','SKIPPED','FAILED','UNCERTAIN')),
  attempt integer NOT NULL CHECK (attempt > 0),
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  outcome jsonb,
  error_class text,
  qloo_correlation_id text,
  PRIMARY KEY (scan_id, stage, attempt)
);

CREATE TABLE IF NOT EXISTS baseline_provider_calls (
  id uuid PRIMARY KEY,
  scan_id uuid REFERENCES baseline_scans(id),
  resolution_id uuid REFERENCES baseline_resolutions(id),
  stage text NOT NULL,
  operation text NOT NULL CHECK (operation IN ('describe','entity_tags','recommend')),
  attempt integer NOT NULL CHECK (attempt > 0),
  status text NOT NULL CHECK (status IN ('DISPATCHING','COMPLETE','FAILED','UNKNOWN')),
  provider_correlation_id text,
  outcome_category text,
  unknown_outcome boolean NOT NULL DEFAULT true,
  dispatched_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  duration_ms integer,
  UNIQUE (scan_id, stage, attempt),
  CHECK ((scan_id IS NULL) <> (resolution_id IS NULL))
);
CREATE INDEX IF NOT EXISTS baseline_provider_calls_scan_idx ON baseline_provider_calls (scan_id, dispatched_at);

CREATE TABLE IF NOT EXISTS baseline_budget_accounts (
  budget_key text PRIMARY KEY,
  limit_calls integer NOT NULL CHECK (limit_calls >= 0),
  used_calls integer NOT NULL DEFAULT 0 CHECK (used_calls >= 0 AND used_calls <= limit_calls),
  updated_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO baseline_budget_accounts (budget_key, limit_calls) VALUES ('qloo', 0) ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS baseline_budget_reservations (
  id uuid PRIMARY KEY,
  scan_id uuid REFERENCES baseline_scans(id),
  provider_call_id uuid NOT NULL UNIQUE REFERENCES baseline_provider_calls(id),
  budget_key text NOT NULL REFERENCES baseline_budget_accounts(budget_key),
  reserved_calls integer NOT NULL CHECK (reserved_calls = 1),
  observed_calls integer NOT NULL DEFAULT 0 CHECK (observed_calls IN (0,1)),
  state text NOT NULL CHECK (state IN ('RESERVED','SETTLED','UNCERTAIN')),
  created_at timestamptz NOT NULL DEFAULT now(),
  settled_at timestamptz
);

CREATE TABLE IF NOT EXISTS baseline_artifacts (
  id uuid PRIMARY KEY,
  scan_id uuid NOT NULL REFERENCES baseline_scans(id),
  stage text,
  schema_version text NOT NULL,
  artifact_type text NOT NULL CHECK (artifact_type IN ('result','observation')),
  payload jsonb NOT NULL,
  source_correlation_ids text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (scan_id, artifact_type, stage)
);
ALTER TABLE baseline_scans ADD CONSTRAINT baseline_scans_result_fk FOREIGN KEY (result_artifact_id) REFERENCES baseline_artifacts(id);
CREATE INDEX IF NOT EXISTS baseline_artifacts_scan_idx ON baseline_artifacts (scan_id, artifact_type);

CREATE TABLE IF NOT EXISTS baseline_execution_events (
  id uuid PRIMARY KEY,
  scan_id uuid NOT NULL REFERENCES baseline_scans(id),
  event_type text NOT NULL,
  stage text,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  metadata jsonb NOT NULL DEFAULT '{}',
  error_class text
);
CREATE INDEX IF NOT EXISTS baseline_events_scan_idx ON baseline_execution_events (scan_id, occurred_at);
